import React, { useEffect, useState } from 'react';
import { getEquipos, getRecursos } from '../services/api';
import StatusBadge from '../components/StatusBadge';
import { LoadingSpinner, ErrorState, EmptyState } from '../components/StateHelpers';

const ROLES = ['Developer', 'Designer', 'Manager', 'DevOps', 'QA', 'Consultor'];

export default function Equipos() {
  const [recursos, setRecursos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    getEquipos()
      .then((d) => { setRecursos(Array.isArray(d) ? d : []); setLoading(false); })
      .catch((e) => { setError(e.message); setLoading(false); });
  }, []);

  if (loading) return <LoadingSpinner />;
  if (error) return <ErrorState message={`Error al cargar equipos. ${error}`} />;

  const gruposPorRol = ROLES.map((rol) => ({
    rol,
    miembros: recursos.filter((r) => r.rol === rol),
  })).filter((g) => g.miembros.length > 0);

  return (
    <div className="section-fade">
      <div className="section-title">Equipos</div>
      <div className="section-sub">Distribución de recursos por equipo</div>

      <div className="data-card">
        <div className="data-card-header">
          <h5>
            <i className="bi bi-diagram-3 me-2" style={{ color: 'var(--accent2)' }}></i>
            Vista de Capacidad
          </h5>
        </div>

        {gruposPorRol.length ? (
          <div style={{ padding: '16px' }}>
            <div className="row g-3">
              {gruposPorRol.map(({ rol, miembros }) => (
                <div className="col-md-4" key={rol}>
                  <div
                    style={{
                      background: 'var(--surface2)',
                      border: '1px solid var(--border)',
                      borderRadius: '12px',
                      padding: '18px',
                    }}
                  >
                    <div
                      style={{
                        fontFamily: "'Syne', sans-serif",
                        fontWeight: 700,
                        marginBottom: '12px',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'space-between',
                      }}
                    >
                      {rol}
                      <span
                        style={{
                          fontSize: '11px',
                          background: 'rgba(79,140,255,0.1)',
                          color: 'var(--accent)',
                          padding: '2px 8px',
                          borderRadius: '10px',
                        }}
                      >
                        {miembros.length}
                      </span>
                    </div>
                    {miembros.map((r) => (
                      <div
                        key={r.id}
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          gap: '8px',
                          padding: '7px 0',
                          borderBottom: '1px solid var(--border)',
                        }}
                      >
                        <div
                          className="avatar"
                          style={{ width: '26px', height: '26px', fontSize: '10px' }}
                        >
                          {(r.nombreRecurso || r.nombre || '?').charAt(0)}
                        </div>
                        <span style={{ fontSize: '13px' }}>
                          {r.nombreRecurso || r.nombre || '—'}
                        </span>
                        <div style={{ marginLeft: 'auto' }}>
                          <StatusBadge estado={r.estado} />
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        ) : (
          <EmptyState message="Sin datos de equipos. Asigna roles a los recursos primero." />
        )}
      </div>
    </div>
  );
}
